class Solution {
public:
    long long minimumSteps(string s) {
        long long ans = 0;
        long long zeros = 0;
        for (int i = (int)s.size() - 1; i >= 0; i--) {
            if (s[i] == '0') {
                zeros++;
            } else {
                ans += zeros;
            }
        }
        return ans;
    }
};
